(()=>{async function hydrate(type,container){try{const r=await fetch('/api/content?type='+type);if(!r.ok)return;const d=await r.json();if(!Array.isArray(d.items)||!d.items.length)return;container.innerHTML=d.items.map((x,i)=>{const image=x.image?`<div class="cms-photo-slot"><img src="${esc(x.image)}" alt="${esc(x.title)}" loading="lazy"></div>`:'';if(type==='experiences')return `<article class="job-card">${image}<div class="job-top"><div><h3>${esc(x.title)}</h3><p>${esc(x.subtitle)}</p></div><span class="date">${esc(x.date)}</span></div>${x.description?`<p>${esc(x.description)}</p>`:''}${x.bullets?.length?`<ul>${x.bullets.map(b=>`<li>${esc(b)}</li>`).join('')}</ul>`:''}</article>`;return `<article class="project-card">${image}<div class="project-num">PROJECT ${String(i+1).padStart(2,'0')}</div><h3>${esc(x.title)}</h3><p>${esc(x.description||x.subtitle||'')}</p>${x.tags?.length?`<div class="tag-list">${x.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`:''}</article>`}).join('')}catch(e){/* Keep the built-in static content when the API is not configured. */}}function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}document.querySelectorAll('[data-cms-list]').forEach(el=>hydrate(el.dataset.cmsList,el))})();